        GroupRecoveryDiagnostics.Trace queued=diagnostics.begin(300);queued.end(GroupRecoveryDiagnostics.Failure.WINDOW_EXPIRED,301);queued.stage(GroupRecoveryDiagnostics.Stage.TCP_CONNECT,302);diagnostics.cancel(303);check(diagnostics.snapshot().stage==GroupRecoveryDiagnostics.Stage.ENDED&&diagnostics.snapshot().attemptedCandidates==0);check(diagnostics.snapshot().failures.size()==1&&diagnostics.snapshot().failures.get(0).stage==GroupRecoveryDiagnostics.Stage.QUEUED&&diagnostics.snapshot().failures.get(0).failure==GroupRecoveryDiagnostics.Failure.WINDOW_EXPIRED);
        tests++;GroupRecoveryPolicy.Attempt retry=attempt();int latePort;try(ServerSocket temporary=new ServerSocket(0,1,InetAddress.getLoopbackAddress())){latePort=temporary.getLocalPort();}check(retry.offer(key,"192.168.1.55",latePort,101));GroupRecoveryPolicy.Endpoint first=retry.poll(101);check(first!=null);
        try(Socket unavailable=new Socket()){try{unavailable.connect(new InetSocketAddress(InetAddress.getLoopbackAddress(),first.port),200);throw new AssertionError("Closed listener unexpectedly available");}catch(ConnectException expected){retry.retry(first,102);}}
        check(retry.poll(1101)==null);check(!retry.offer(key,first.host,first.port,1102));try(ServerSocket delayed=new ServerSocket()){delayed.setReuseAddress(true);delayed.bind(new InetSocketAddress(InetAddress.getLoopbackAddress(),latePort));GroupRecoveryPolicy.Endpoint again=retry.poll(1102);check(again==first);try(Socket connection=new Socket(InetAddress.getLoopbackAddress(),again.port);Socket accepted=delayed.accept()){connection.getOutputStream().write(37);check(accepted.getInputStream().read()==37);}check(retry.complete(1103));retry.retry(again,1104);check(retry.poll(9999)==null);}
        tests++;GroupRecoveryPolicy.Attempt bounded=attempt();check(bounded.offer(key,"192.168.1.55",40000,100));long[] times={100,1100,4100,12100,20100};for(long at:times){GroupRecoveryPolicy.Endpoint next=bounded.poll(at);check(next!=null);bounded.retry(next,at);check(bounded.poll(at)==null);}check(bounded.poll(40000)==null);check(!bounded.offer(key,"192.168.1.55",40000,40001));check(bounded.offer(key,"192.168.1.56",40000,40001));GroupRecoveryPolicy.Endpoint alternative=bounded.poll(40001);check(alternative!=null&&alternative.host.endsWith("56"));bounded.cancel();bounded.retry(alternative,40002);check(bounded.poll(40003)==null);
        tests++;AtomicBoolean departingClosed=new AtomicBoolean(),departingDetached=new AtomicBoolean();CountDownLatch offerEntered=new CountDownLatch(1),departingNow=new CountDownLatch(1);AtomicReference<Throwable> deliveryFailure=new AtomicReference<>();Thread heartbeat=new Thread(()->{try{check(!GroupPeerDelivery.offer(departingClosed::get,()->{offerEntered.countDown();if(!departingNow.await(1,TimeUnit.SECONDS))throw new AssertionError("Close race not released");if(departingClosed.get())throw new java.io.IOException("closed during queue offer");},()->departingDetached.set(true)));}catch(Throwable problem){deliveryFailure.set(problem);}});heartbeat.start();check(offerEntered.await(1,TimeUnit.SECONDS));departingClosed.set(true);departingNow.countDown();heartbeat.join(1000);check(!heartbeat.isAlive()&&deliveryFailure.get()==null&&departingDetached.get());
